    slide.background = { color: colors.bgDark };
    slide.addShape(pptx.ShapeType.rect, { x: 0, y: 0, w: 13.33, h: 0.18, fill: { color: colors.accent }, line: { color: colors.accent } });
    slide.addText(title, {
      x: 0.6, y: 0.45, w: 11.8, h: 0.6,
      fontFace: 'Calibri', fontSize: 34, bold: true, color: 'FFFFFF'
    });
    if (subtitle) slide.addText(subtitle, {
      x: 0.6, y: 1.08, w: 11.8, h: 0.4,
      fontFace: 'Calibri', fontSize: 16, color: colors.textLight
    });
  } else {
    slide.background = { color: colors.bgLight };
    slide.addShape(pptx.ShapeType.rect, { x: 0, y: 0, w: 13.33, h: 0.14, fill: { color: colors.primary }, line: { color: colors.primary } });
    slide.addText(title, {
      x: 0.6, y: 0.32, w: 11.8, h: 0.56,
      fontFace: 'Calibri', fontSize: 30, bold: true, color: colors.textDark
    });
    if (subtitle) slide.addText(subtitle, {
      x: 0.6, y: 0.88, w: 11.8, h: 0.36,
      fontFace: 'Calibri', fontSize: 14, color: colors.muted
    });
  }
}

